def worst_case_cow_gb(writes_per_sec: int, duration_s: int, page_kb: int, dataset_gb: float) -> float:
    touched_gb = (writes_per_sec * duration_s * page_kb) / (1024 * 1024)
    return min(dataset_gb, touched_gb)
# 4 KB pages -> 5.15 GB; 2 MB THP -> capped at full 24.0 GB!
